import XCTest
@MainActor final class CompanionSaveJourneyTests:XCTestCase {
 private func tap(_ id:String,_ app:XCUIApplication){let b=app.buttons[id];XCTAssertTrue(b.waitForExistence(timeout:15),id);XCTAssertTrue(b.isHittable,id);b.tap()}
 private func photo(_ name:String,_ app:XCUIApplication){let a=XCTAttachment(screenshot:XCUIScreen.main.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
 func testHomeAndNestedGoalDeniedSDKSaveKeepChoiceAllowInteractionExpireAndRestoreWithoutToast(){
  continueAfterFailure=false;let app=XCUIApplication();app.launchEnvironment=["PIYALI_OFFLINE_TESTS":"1","PIYALI_TEST_IDENTITY_SCOPE":UUID().uuidString,"PIYALI_ENTRY_INITIAL_LANGUAGE":"en","PIYALI_ENTRY_INITIAL_THEME":"light","PIYALI_SETTINGS_FIXTURE":"1","PIYALI_HEADLINE_FIXTURE":"failure","PIYALI_COMPANION_SAVE_FIXTURE":"failure","PIYALI_RULES_EMULATOR_TESTS":"1"];app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];app.launch();handleInitialPaperPencil(app);let entry=app.textFields["entryName"];XCTAssertTrue(entry.waitForExistence(timeout:15));entry.tap();entry.typeText("Companion Save Learner");tap("entryKeyboardDone",app);tap("createAccount",app);handleInitialPaperPencil(app);tap("startLearning",app);tap("focusCustomizeCompanion",app)
  let field=app.textFields["companionNameDraft"];XCTAssertTrue(field.waitForExistence(timeout:8));field.tap();field.typeText("Nova\n");let title=app.staticTexts.matching(NSPredicate(format:"identifier == %@ AND label == %@","companionSaveNoticeTitle","Save failed")).firstMatch;XCTAssertTrue(title.waitForExistence(timeout:12));photo("Companion Home save denied",app);XCTAssertTrue(app.staticTexts["Nova"].exists);XCTAssertTrue(app.buttons["openDailyGoal"].isHittable);tap("openDailyGoal",app);XCTAssertTrue(app.buttons["dailyGoalClose"].waitForExistence(timeout:10));tap("goalCompanionEdit",app);XCTAssertTrue(field.waitForExistence(timeout:8));XCTAssertEqual(field.value as? String,"Nova");field.tap();field.typeText(" Luz\n");XCTAssertTrue(title.waitForExistence(timeout:12));photo("Companion Goal save denied above manager",app);XCTAssertTrue(app.buttons["goalCompanionEdit"].isHittable)
  let expired=expectation(for:NSPredicate(format:"exists == false"),evaluatedWith:title);wait(for:[expired],timeout:9);tap("dailyGoalClose",app);XCTAssertFalse(field.exists);app.terminate();app.launch();handleInitialPaperPencil(app);XCTAssertTrue(app.buttons["productMenu"].waitForExistence(timeout:15));XCTAssertFalse(title.exists);tap("focusCustomizeCompanion",app);XCTAssertTrue(field.waitForExistence(timeout:8));XCTAssertEqual(field.value as? String,"Nova Luz");XCTAssertFalse(title.exists);photo("Companion failed save restored locally without replay",app)
 }
}
